        MAP
    NAME "SS_MAP_RFRE_ANTENAS_RF"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
                INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    DEBUG 5
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_antenasrf.log"
        SYMBOL
        NAME "badgerse"
        TYPE pixmap
        IMAGE "includes/symbols/BadgerSE.png"
    END #SYMBOL
    SYMBOL
        NAME "badgerce"
        TYPE pixmap
        IMAGE "includes/symbols/BadgerCE.png"
    END #SYMBOL
    SYMBOL
        NAME "kamstrup"
        TYPE pixmap
        IMAGE "includes/symbols/Kamstrup.png"
    END #SYMBOL
    SYMBOL
        NAME "sensus"
        TYPE pixmap
        IMAGE "includes/symbols/Sensus.png"
    END #SYMBOL
    LAYER
        NAME "SS_MAP_RFRE_ANTENAS_RF"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION   
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        TYPE POINT
        DATA "geometry from op.l_antenas_radio_frecuencia using unique id using srid=32614"
        LABELCACHE ON
        MAXSCALE 5000
        SYMBOLSCALEDENOM 4000
        CLASSITEM "cl_tipo"
        CLASS
            NAME "BADGER SE"
            TEMPLATE "x.html"
            EXPRESSION "A3"
            STYLE
                SYMBOL "badgerse"
                SIZE 30
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "BADGER CE"
            TEMPLATE "x.html"
            EXPRESSION "A8"
            STYLE
                SYMBOL "badgerce"
                SIZE 30                    
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS    
        CLASS
            NAME "KAMSTRUP"
            TEMPLATE "x.html"
            EXPRESSION "X"
            STYLE
                SYMBOL "kamstrup"
                SIZE 30               
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "SENSUS"
            TEMPLATE "x.html"
            EXPRESSION "F"
            STYLE
                SYMBOL "sensus"
                SIZE 30
                OFFSET 0 30               
            END#STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial" 
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS               
    END #LAYER
    LAYER
        NAME "SS_MAP_RFRE_ANTENAS_RF_SCALA"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        TYPE POINT
        DATA "geometry from op.l_antenas_radio_frecuencia using unique id using srid=32614"
        LABELCACHE OFF
        MINSCALE 5100
        CLASSITEM "cl_tipo"
        CLASS
            NAME "BADGER SE"
            TEMPLATE "x.html"
            EXPRESSION "A3"
            STYLE
                SYMBOL "badgerse"
                SIZE 30
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "BADGER CE"
            TEMPLATE "x.html"
            EXPRESSION "A8"
            STYLE
                SYMBOL "badgerce"
                SIZE 30
            END #STYLE
            LABEL             
                TYPE TRUETYPE
                FONT "arial"
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS    
        CLASS
            NAME "KAMSTRUP"
            TEMPLATE "x.html"
            EXPRESSION "X"
            STYLE
                SYMBOL "kamstrup"
                SIZE 30
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "SENSUS"
            TEMPLATE "x.html"
            EXPRESSION "F"
            STYLE
                SYMBOL "sensus"
                SIZE 30              
            END#STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 12
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS               
    END #LAYER
END #MAP 
